INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "リンド", -470, 10005, 1, 2, 2002, 2, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", "2023/12/22 14:59:59", 127702, 0, "2023/09/15 15:00:00", 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "リンド", -470, 10006, 2, 2, 2002, 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", "2023/12/22 14:59:59", 127702, 0, "2023/09/15 15:00:00", 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ヴルム", -470, 10007, 1, 1, 2002, 1, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", "2023/12/22 14:59:59", 127802, 0, "2023/09/15 15:00:00", 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.5, "ヴルム", -470, 10008, 2, 2, 2002, 1, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", "2023/12/22 14:59:59", 127802, 0, "2023/09/15 15:00:00", 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "アネモネ", -470, 10009, 1, 2, 2002, 1, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", "2024/03/22 14:59:59", 129602, 0, "2023/12/15 15:00:00", 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "アネモネ", -470, 10010, 2, 2, 2002, 1, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", "2024/03/22 14:59:59", 129602, 0, "2023/12/15 15:00:00", 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ネフィ=ネラ", -470, 10011, 1, 1, 2002, 1, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", "2024/03/22 14:59:59", 129701, 0, "2023/12/15 15:00:00", 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.2, "ネフィ=ネラ", -470, 10012, 2, 2, 2002, 1, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", "2024/03/22 14:59:59", 129701, 0, "2023/12/15 15:00:00", 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.1, "カノン", -470, 10013, 1, 3, 2002, 5, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", "2024/06/22 14:59:59", 130301, 0, "2024/03/15 15:00:00", 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.15, "カノン", -470, 10014, 2, 3, 2002, 2, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", "2024/06/22 14:59:59", 130301, 0, "2024/03/15 15:00:00", 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ナーナ", -470, 10015, 1, 2, 2002, 2, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", "2024/06/22 14:59:59", 130401, 0, "2024/03/15 15:00:00", 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.35, "ナーナ", -470, 10016, 2, 2, 2002, 1, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", "2024/06/22 14:59:59", 130401, 0, "2024/03/15 15:00:00", 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ホウオウ", -470, 10017, 1, 1, 2002, 1, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", "2024/09/22 14:59:59", 130502, 0, "2024/06/15 15:00:00", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.18, "ホウオウ", -470, 10018, 2, 2, 2002, 1, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", "2024/09/22 14:59:59", 130502, 0, "2024/06/15 15:00:00", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ホウオウ", -470, 10019, 3, 4, 2002, 4, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", "2024/09/22 14:59:59", 130503, 0, "2024/06/15 15:00:00", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.9, "ネア", -470, 10020, 1, 1, 2002, 2, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", "2024/09/22 14:59:59", 123301, 0, "2024/06/15 15:00:00", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.8, "ネア", -470, 10021, 2, 1, 2002, 2, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", "2024/09/22 14:59:59", 123301, 0, "2024/06/15 15:00:00", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.922, "カリザ", -470, 10022, 1, 3, 2002, 1, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", "2024/12/22 14:59:59", 133301, 0, "2024/09/15 15:00:00", 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (9.638, "カリザ", -470, 10023, 2, 3, 2002, 5, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", "2024/12/22 14:59:59", 133301, 0, "2024/09/15 15:00:00", 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2.88, "ミーア", -470, 10024, 1, 1, 2002, 2, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", "2024/12/22 14:59:59", 133401, 0, "2024/09/15 15:00:00", 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.818, "ミーア", -470, 10025, 2, 5, 2002, 1, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", "2024/12/22 14:59:59", 133401, 0, "2024/09/15 15:00:00", 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1.78, "グレイス", -470, 10026, 1, 2, 2002, 1, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", "2025/03/22 14:59:59", 133002, 0, "2024/12/15 15:00:00", 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.15, "グレイス", -470, 10027, 2, 1, 2002, 7, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", "2025/03/22 14:59:59", 133002, 0, "2024/12/15 15:00:00", 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.28, "ヴァイオレット", -470, 10028, 1, 6, 2002, 2, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", "2025/03/22 14:59:59", 133102, 0, "2024/12/15 15:00:00", 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ヴァイオレット", -470, 10029, 2, 1, 2002, 1, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", "2025/03/22 14:59:59", 133102, 0, "2024/12/15 15:00:00", 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.53, "ルルィ", -470, 10030, 1, 2, 2002, 1, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", "2025/06/23 14:59:59", 136902, 0, "2025/03/15 15:00:00", 8);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.05, "ルルィ", -470, 10031, 2, 9, 2002, 7, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", "2025/06/23 14:59:59", 136902, 0, "2025/03/15 15:00:00", 8);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "デュラン", -470, 10032, 1, 2, 2002, 1, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", "2025/06/23 14:59:59", 137001, 0, "2025/03/15 15:00:00", 8);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "デュラン", -470, 10033, 2, 2, 2002, 1, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", "2025/06/23 14:59:59", 137001, 0, "2025/03/15 15:00:00", 8);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "サツキ", -470, 10034, 1, 2, 2002, 2, "おう\n好きなもん持ってきな", "2025/09/23 14:59:59", 135902, 0, "2025/06/16 15:00:00", 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.935, "サツキ", -470, 10035, 2, 1, 2002, 6, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", "2025/09/23 14:59:59", 135902, 0, "2025/06/16 15:00:00", 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (7.441, "ユキノ", -470, 10036, 1, 2, 2002, 5, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", "2025/09/23 14:59:59", 135802, 0, "2025/06/16 15:00:00", 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ユキノ", -470, 10037, 2, 7, 2002, 7, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", "2025/09/23 14:59:59", 135802, 0, "2025/06/16 15:00:00", 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2.295, "クルル", -470, 10038, 1, 2, 2002, 2, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", "2025/12/22 14:59:59", 130901, 0, "2025/09/16 15:00:00", 10);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (6.281, "クルル", -470, 10039, 2, 1, 2002, 6, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", "2025/12/22 14:59:59", 130901, 0, "2025/09/16 15:00:00", 10);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.549, "ヴォルガーノ", -470, 10040, 1, 2, 2002, 1, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", "2025/12/22 14:59:59", 137701, 0, "2025/09/16 15:00:00", 10);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2.64, "ヴォルガーノ", -470, 10041, 2, 3, 2002, 6, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", "2025/12/22 14:59:59", 137701, 0, "2025/09/16 15:00:00", 10);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (7.642, "ライラエル", -470, 10042, 1, 7, 2002, 4, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", "2026/03/23 11:59:59", 132801, 0, "2025/12/15 15:00:00", 11);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ライラエル", -470, 10043, 2, 1, 2002, 1, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", "2026/03/23 11:59:59", 132802, 0, "2025/12/15 15:00:00", 11);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "クローチェ", -470, 10044, 1, 1, 2002, 1, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", "2026/03/23 11:59:59", 134502, 0, "2025/12/15 15:00:00", 11);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.72, "クローチェ", -470, 10045, 2, 2, 2002, 1, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", "2026/03/23 11:59:59", 134501, 0, "2025/12/15 15:00:00", 11);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.991, "ネフィ＝ネラ", -470, 10046, 1, 2, 2002, 1, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", "2026/06/22 11:59:59", 138201, 0, "2026/03/16 12:00:00", 12);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.877, "ネフィ＝ネラ", -470, 10047, 2, 1, 2002, 4, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", "2026/06/22 11:59:59", 138201, 0, "2026/03/16 12:00:00", 12);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1.71, "アラクネ", -470, 10048, 1, 4, 2002, 6, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", "2026/06/22 11:59:59", 136001, 0, "2026/03/16 12:00:00", 12);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.32, "アラクネ", -470, 10049, 2, 5, 2002, 2, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", "2026/06/22 11:59:59", 136001, 0, "2026/03/16 12:00:00", 12);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3.727, "アネモネ", -470, 10050, 1, 9, 2002, 4, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", "2026/09/22 11:59:59", 135401, 0, "2026/06/15 12:00:00", 13);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (7.213, "アネモネ", -470, 10051, 2, 7, 2002, 9, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", "2026/09/22 11:59:59", 135401, 0, "2026/06/15 12:00:00", 13);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1.874, "クリア", -470, 10052, 1, 1, 2002, 2, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", "2026/09/22 11:59:59", 135301, 0, "2026/06/15 12:00:00", 13);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "クリア", -470, 10053, 2, 2, 2002, 2, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", "2026/09/22 11:59:59", 135301, 0, "2026/06/15 12:00:00", 13);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (4.215, "ヴァイオレット", -470, 10054, 1, 2, 2002, 1, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", "2026/12/22 11:59:59", 138001, 0, "2026/09/15 12:00:00", 14);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (0, "ヴァイオレット", -470, 10055, 2, 4, 2002, 4, "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", "2026/12/22 11:59:59", 138001, 0, "2026/09/15 12:00:00", 14);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.477, "グレイス", -470, 10056, 1, 6, 2002, 1, "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", "2026/12/22 11:59:59", 138901, 0, "2026/09/15 12:00:00", 14);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (5.743, "グレイス", -470, 10057, 2, 2, 2002, 1, "どうも。グレイスちゃん\n客寄せバージョンですぴょん\n一名様ごあんな～い", "2026/12/22 11:59:59", 138901, 0, "2026/09/15 12:00:00", 14);
